const cfg = $('Config').first().json;

// ---- EDIT YOUR KEYWORDS HERE ----
const keywords = [
  'Node.js backend developer', 'backend developer', 'Python developer', 'Django developer',
  'AI engineer', 'AI developer', 'AI application developer', 'Generative AI', 'RAG LangChain', 'LangGraph',
  'SOC analyst L1', 'VAPT', 'network security',
  'full stack developer', 'web developer', 'C programming'
];

const hours = Number(cfg.postedWithinHours) || 24;
const days = Math.max(1, Math.ceil(hours / 24));
const out = [];

for (const kw of keywords) {
  const q = encodeURIComponent(kw);
  const slug = kw.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

  // LinkedIn (public guest endpoint). f_E=1,2 => Internship + Entry level
  out.push({ json: { source: 'linkedin', keyword: kw,
    url: `https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search?keywords=${q}&location=${encodeURIComponent('Bengaluru, Karnataka, India')}&f_E=1%2C2&f_TPR=r${hours * 3600}&start=0` } });

  // Naukri (unofficial JSON endpoint). experience=0 => fresher
  out.push({ json: { source: 'naukri', keyword: kw,
    url: `https://www.naukri.com/jobapi/v3/search?noOfResults=20&urlType=search_by_keyword&searchType=adv&keyword=${q}&location=bengaluru&k=${q}&l=bengaluru&experience=0&jobAge=${days}&sort=f&pageNo=1&src=jobsearchDesk&seoKey=${slug}-jobs-in-bengaluru&sid=` } });

  // Hirist (unofficial JSON endpoint - may need adjusting)
  out.push({ json: { source: 'hirist', keyword: kw,
    url: `https://gladiator.hirist.tech/job/search?pageNo=0&query=${q}&minexp=0&maxexp=1&range=0&boolean=true&searchRange=${days}` } });
}
return out;

const strip = s => (s || '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
const jobs = [];
for (const it of $input.all()) {
  const html = it.json.data;
  if (typeof html !== 'string') continue;
  for (const c of html.split(/<li[^>]*>/).slice(1)) {
    const id = (c.match(/jobPosting:(\d+)/) || [])[1];
    if (!id) continue;
    const title = strip((c.match(/base-search-card__title[^>]*>([\s\S]*?)<\/h3>/) || [])[1]);
    const company = strip((c.match(/base-search-card__subtitle[^>]*>([\s\S]*?)<\/h4>/) || [])[1]);
    const location = strip((c.match(/job-search-card__location[^>]*>([\s\S]*?)<\/span>/) || [])[1]);
    const link = (((c.match(/base-card__full-link[^>]*href="([^"]+)"/) || [])[1]) || ((c.match(/href="([^"]+)"/) || [])[1]) || '').replace(/&amp;/g, '&').split('?')[0];
    const posted = (c.match(/datetime="([^"]+)"/) || [])[1] || '';
    if (title) jobs.push({ json: { source: 'LinkedIn', jobId: 'li-' + id, linkedinId: id, title, company, location, experience: '', link, posted, description: '' } });
  }
}
return jobs;

const strip = s => (s || '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const jobs = [];
for (const it of $input.all()) {
  const list = it.json.jobDetails;
  if (!Array.isArray(list)) continue;
  for (const j of list) {
    const ph = j.placeholders || [];
    const location = (ph.find(p => p.type === 'location') || {}).label || '';
    const experience = (ph.find(p => p.type === 'experience') || {}).label || '';
    const link = j.jdURL ? (j.jdURL.startsWith('http') ? j.jdURL : 'https://www.naukri.com' + j.jdURL) : '';
    jobs.push({ json: { source: 'Naukri', jobId: 'nk-' + j.jobId, title: strip(j.title), company: strip(j.companyName), location, experience, link,
      posted: j.footerPlaceholderLabel || '', description: strip(j.jobDescription) + (j.tagsAndSkills ? ' Skills: ' + j.tagsAndSkills : '') } });
  }
}
return jobs;

const strip = s => (s || '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const jobs = [];
for (const it of $input.all()) {
  const d = it.json;
  const list = d.jobs || (d.data && d.data.jobs) || (Array.isArray(d.data) ? d.data : null) || d.jobList || d.results || [];
  if (!Array.isArray(list)) continue;
  for (const j of list) {
    const id = j.id || j.jobId;
    if (!id) continue;
    const location = Array.isArray(j.locations) ? j.locations.map(l => l.name || l).join(', ') : (j.location || '');
    const company = (j.companyData && j.companyData.companyName) || j.companyName || (j.company && j.company.name) || '';
    const skills = Array.isArray(j.skills) ? j.skills.map(s => s.name || s).join(', ') : '';
    const experience = (j.min !== undefined && j.max !== undefined) ? `${j.min}-${j.max} Yrs` : (j.experience || '');
    jobs.push({ json: { source: 'Hirist', jobId: 'hr-' + id, title: strip(j.title || j.jobTitle), company: strip(company), location, experience,
      link: j.jobDetailUrl || ('https://www.hirist.tech/j/' + id), posted: j.createdTimeMs ? new Date(j.createdTimeMs).toISOString() : '', description: skills ? 'Skills: ' + skills : '' } });
  }
}
return jobs;

const cityRe = /bengaluru|bangalore|bengalore|whitefield|electronic city|koramangala|hsr layout|indiranagar|marathahalli|bellandur|sarjapur|hebbal|yelahanka|jp nagar|jayanagar|btm layout|mg road|manyata|outer ring road|domlur|kr puram|banashankari|rajajinagar|malleshwaram|devanahalli|bommanahalli|cv raman nagar|hosur road/i;
const seniorRe = /\b(senior|sr\.?|lead|principal|staff|manager|architect|head|director|vp|ii|iii|iv)\b|\bsde[\s-]*(2|3|ii|iii)\b|\blevel\s*[2-9]\b/i;
const MAX_MIN_EXP = 1;   // job may not ask for more than this many years minimum
const MAX_MAX_EXP = 3;   // for "x-y years" labels, y may not exceed this
const norm = s => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const seen = new Set();
const bySource = {};
for (const it of $input.all()) {
  const j = it.json;
  if (!j.title) continue;
  if (j.location && !cityRe.test(j.location)) continue;
  if (seniorRe.test(j.title)) continue;

  const label = j.experience || '';
  const r = label.match(/(\d+)\s*(?:-|–|to)\s*(\d+)/);
  const s = label.match(/(\d+)\s*\+?\s*(?:years?|yrs?)/i);
  if (r && (Number(r[1]) > MAX_MIN_EXP || Number(r[2]) > MAX_MAX_EXP)) continue;
  if (!r && s && Number(s[1]) > MAX_MIN_EXP) continue;

  const key = norm(j.company) + '|' + norm(j.title);
  if (seen.has(key)) continue;
  seen.add(key);
  (bySource[j.source] = bySource[j.source] || []).push({ ...j, dedupeKey: key });
}

// interleave sources so a later Limit doesn't favour LinkedIn
const lists = Object.values(bySource);
const out = [];
for (let i = 0; lists.some(l => i < l.length); i++) {
  for (const l of lists) if (i < l.length) out.push({ json: l[i] });
}
return out;

const orig = $('Limit Jobs').item.json;
let description = '';
const html = $json.data;
if (typeof html === 'string') {
  const m = html.match(/show-more-less-html__markup[^>]*>([\s\S]*?)<\/div>/);
  if (m) {
    description = m[1]
      .replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|ul|ol)>/gi, '\n').replace(/<li[^>]*>/gi, '\n- ')
      .replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
      .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
  }
}
return { json: { ...orig, description } };

const MAX_MIN_EXP = 1;
const cap = Number($('Config').first().json.maxJobsPerRun) || 30;
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const text = `${j.title}. ${j.description || ''}`;
  const mins = [];
  for (const seg of text.split(/[\n.•;]+/)) {
    if (!/\b(years?|yrs?)\b/i.test(seg)) continue;
    if (!/(experience|exp\b|relevant|hands-on|work)/i.test(seg)) continue;
    if (/\b(we|our|company|founded|established)\b/i.test(seg)) continue;
    const range = seg.match(/(\d+)\s*\+?\s*(?:-|–|to)\s*(\d+)\s*\+?\s*(?:years?|yrs?)/i);
    const single = seg.match(/(\d+)\s*\+?\s*(?:years?|yrs?)/i);
    if (range) mins.push(Number(range[1]));
    else if (single) mins.push(Number(single[1]));
  }
  if (mins.length && Math.min(...mins) > MAX_MIN_EXP) continue;   // asks for 2+ years
  if (!j.experience) j.experience = mins.length ? `${Math.min(...mins)}+ yrs (from JD)` : 'not stated';
  out.push({ json: j });
}
return out.slice(0, cap);

const cfg = $('Config').first().json;
const system = `You are a career assistant for a fresher job seeker in India. Read the job posting and answer ONLY with a valid JSON object (no markdown) with these keys:
{
 "summary": "2-3 plain sentences: what the company/role is and what you will actually do",
 "role_type": "short label e.g. Backend (Python/Django), GenAI Engineer, SOC L1, VAPT, Full Stack",
 "experience_required": "what the posting says, or 'not stated'",
 "fresher_friendly": true or false,
 "must_have_skills": ["max 8 core skills/tools from the posting"],
 "resume_keywords": ["8-15 ATS keywords/phrases from THIS posting that the candidate should add to the resume, only ones the candidate can truthfully claim based on their profile"],
 "skills_gap": ["up to 4 required skills the candidate seems to lack and should learn"],
 "fit_score": integer 1-10 for this candidate,
 "red_flags": "anything suspicious or discouraging (unpaid, senior-level, 3+ years, vague, pay-to-join) or 'none'"
}
If the posting text is short, infer carefully from the title and say so in the summary. Never invent facts.`;

return $input.all().map(it => {
  const j = it.json;
  const desc = (j.description || '').slice(0, 3500);
  const user = `CANDIDATE PROFILE:\n${cfg.candidateProfile}\n\nJOB:\nTitle: ${j.title}\nCompany: ${j.company}\nLocation: ${j.location}\nExperience: ${j.experience || 'not stated'}\nSource: ${j.source}\n\nDESCRIPTION:\n${desc || '(not available - only title provided)'}`;
  return { json: { ...j, groqBody: {
    model: cfg.groqModel || 'llama-3.3-70b-versatile',
    temperature: 0.2,
    max_tokens: 800,
    response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }]
  } } };
});

let job;
try { job = $('Loop Over Jobs').item.json; } catch (e) { job = $('Loop Over Jobs').first().json; }

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let ai = null;
try {
  const content = $json.choices[0].message.content;
  ai = JSON.parse(content);
} catch (e) { ai = null; }

const lines = [];
lines.push(`🆕 <b>${esc(job.title)}</b>`);
lines.push(`🏢 ${esc(job.company || 'N/A')}  ·  📍 ${esc(job.location || 'Bengaluru')}  ·  🔎 ${esc(job.source)}`);
if (job.experience) lines.push(`💼 Exp: ${esc(job.experience)}`);
if (job.posted) lines.push(`🕒 ${esc(job.posted)}`);
lines.push('');

if (ai) {
  lines.push(`📝 ${esc(ai.summary)}`);
  lines.push('');
  lines.push(`🎯 <b>Fit:</b> ${esc(ai.fit_score)}/10  |  <b>Type:</b> ${esc(ai.role_type)}  |  <b>Fresher-friendly:</b> ${ai.fresher_friendly ? 'Yes' : 'No'}`);
  if (ai.experience_required) lines.push(`📅 <b>Experience asked:</b> ${esc(ai.experience_required)}`);
  if (Array.isArray(ai.must_have_skills) && ai.must_have_skills.length) lines.push(`🛠 <b>Must-have:</b> ${esc(ai.must_have_skills.join(', '))}`);
  if (Array.isArray(ai.resume_keywords) && ai.resume_keywords.length) {
    lines.push('');
    lines.push(`🔑 <b>Add to resume:</b>\n<code>${esc(ai.resume_keywords.join(', '))}</code>`);
  }
  if (Array.isArray(ai.skills_gap) && ai.skills_gap.length) lines.push(`📚 <b>Learn:</b> ${esc(ai.skills_gap.join(', '))}`);
  if (ai.red_flags && String(ai.red_flags).toLowerCase() !== 'none') lines.push(`⚠️ ${esc(ai.red_flags)}`);
} else {
  lines.push('⚠️ AI summary unavailable for this job (Groq error or rate limit).');
}
lines.push('');
lines.push(job.link ? `🔗 <a href="${esc(job.link)}">Apply / View job</a>` : '🔗 No link found');

let text = lines.join('\n');
if (text.length > 4000) text = text.slice(0, 3990) + '…';
return { json: { text } };
